changeSet.sql:
ALTER TABLE issue_type ADD COLUMN native_id varchar(128);
UPDATE issue_type SET native_id = id;
ALTER TABLE issue_type ALTER COLUMN native_id SET NOT NULL;
ALTER TABLE issue_type ADD COLUMN new_id bigint;
UPDATE issue_type t SET new_id = n.number
FROM (SELECT id, row_number() OVER (ORDER BY organization_id, id) AS number FROM issue_type) n
WHERE n.id = t.id;

-- An issue keeps its type when the type's organization is on the issue's provider instance.
-- Otherwise its type moves to the root group of the issue's own organization (or that organization).
CREATE TEMPORARY TABLE issue_type_move ON COMMIT DROP AS
SELECT i.id AS issue_id, t.id AS type_id, t.native_id, COALESCE(root.id, o.id) AS organization_id
FROM issue i
JOIN issue_type t ON t.id = i.issue_type_id
JOIN organization type_org ON type_org.id = t.organization_id
JOIN repository r ON r.id = i.repository_id
JOIN organization o ON o.id = r.organization_id
LEFT JOIN organization root ON root.provider_id = o.provider_id AND root.login = split_part(o.login, '/', 1)
WHERE o.provider_id <> type_org.provider_id;

INSERT INTO issue_type (id, new_id, native_id, name, description, color, is_enabled, organization_id, last_sync_at)
SELECT 'moved:' || c.new_id, c.new_id, c.native_id, t.name, t.description, t.color, t.is_enabled, c.organization_id, NULL
FROM (SELECT m.organization_id, m.native_id, min(m.type_id) AS type_id,
             COALESCE((SELECT max(new_id) FROM issue_type), 0)
                 + row_number() OVER (ORDER BY m.organization_id, m.native_id) AS new_id
      FROM issue_type_move m
      WHERE NOT EXISTS (SELECT 1 FROM issue_type e
                        WHERE e.organization_id = m.organization_id AND e.native_id = m.native_id)
      GROUP BY m.organization_id, m.native_id) c
JOIN issue_type t ON t.id = c.type_id;

ALTER TABLE issue DROP CONSTRAINT fk_issue_issue_type;
UPDATE issue i SET issue_type_id = t.new_id::text
FROM issue_type t WHERE t.id = i.issue_type_id;
UPDATE issue i SET issue_type_id = t.new_id::text
FROM issue_type_move m JOIN issue_type t ON t.organization_id = m.organization_id AND t.native_id = m.native_id
WHERE i.id = m.issue_id;

ALTER TABLE issue_type DROP CONSTRAINT issue_type_pkey;
UPDATE issue_type SET id = new_id::text;
ALTER TABLE issue_type ALTER COLUMN id TYPE bigint USING id::bigint;
ALTER TABLE issue_type DROP COLUMN new_id;
ALTER TABLE issue_type ADD CONSTRAINT issue_type_pkey PRIMARY KEY (id);
ALTER TABLE issue_type ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
SELECT setval(pg_get_serial_sequence('issue_type', 'id'), COALESCE((SELECT max(id) FROM issue_type), 0) + 1, false);
ALTER TABLE issue_type ADD CONSTRAINT uq_issue_type_organization_native_id UNIQUE (organization_id, native_id);
-- The unique index leads with organization_id, so it serves the organization foreign key.
DROP INDEX idx_issue_type_organization_id;

ALTER TABLE issue ALTER COLUMN issue_type_id TYPE bigint USING issue_type_id::bigint;
ALTER TABLE issue ADD CONSTRAINT fk_issue_issue_type FOREIGN KEY (issue_type_id) REFERENCES issue_type(id) ON DELETE SET NULL;
